add_action( 'admin_init', 'perfectpixel_heartbeat_settings_fields' );
add_filter( 'heartbeat_settings', 'perfectpixel_heartbeat_interval' );
add_action( 'wp_enqueue_scripts', 'perfectpixel_heartbeat_frontend', 100 );

function perfectpixel_heartbeat_settings_fields() {
	register_setting( 'general', 'perfectpixel_heartbeat_interval', array( 'type' => 'integer', 'sanitize_callback' => 'absint', 'default' => 0 ) );
	register_setting( 'general', 'perfectpixel_heartbeat_frontend_off', array( 'type' => 'boolean', 'sanitize_callback' => 'rest_sanitize_boolean', 'default' => false ) );
	add_settings_field( 'perfectpixel_heartbeat_interval', 'Heartbeat', 'perfectpixel_heartbeat_settings_html', 'general' );
}

function perfectpixel_heartbeat_settings_html() {
	$current = (int) get_option( 'perfectpixel_heartbeat_interval' );
	echo '<select name="perfectpixel_heartbeat_interval">';
	echo '<option value="0"' . selected( $current, 0, false ) . '>Προεπιλογή WordPress</option>';
	foreach ( array( 15, 30, 60, 90, 120 ) as $seconds ) {
		echo '<option value="' . (int) $seconds . '"' . selected( $current, $seconds, false ) . '>' . (int) $seconds . ' δευτερόλεπτα</option>';
	}
	echo '</select>';
	echo '<p><label><input type="checkbox" name="perfectpixel_heartbeat_frontend_off" value="1"' . checked( (bool) get_option( 'perfectpixel_heartbeat_frontend_off' ), true, false ) . '> Απενεργοποίηση στις σελίδες του site</label></p>';
}

function perfectpixel_heartbeat_interval( $settings ) {
	$seconds = (int) get_option( 'perfectpixel_heartbeat_interval' );
	if ( $seconds ) {
		$settings['interval'] = min( 120, max( 15, $seconds ) );
	}
	return $settings;
}

function perfectpixel_heartbeat_frontend() {
	if ( get_option( 'perfectpixel_heartbeat_frontend_off' ) ) {
		wp_dequeue_script( 'heartbeat' );
	}
}
